    static UInt8 execute(size_t i, size_t width)
    {
        return static_cast<UInt8>((i >> 1) & ((1 << width) - 1));
    }
};

struct Generator3
{
    static UInt8 execute(size_t i, size_t width)
    {
        return static_cast<UInt8>((i * 17 + 31) % (1ULL << width));
    }
};

