    watch.restart();

    for (size_t i = 0; i < num_threads; ++i)
        pool.scheduleOrThrowOnError([&, i] {
            auto begin = data.begin() + (data.size() * i) / num_threads;
            auto end = data.begin() + (data.size() * (i + 1)) / num_threads;
