        watch.stop();
        double elapsed = watch.elapsedSeconds();
        if (!ok)
            std::cerr
                << "Checked in " << elapsed
                << " (" << static_cast<double>(limit) / elapsed << " elem/sec., "
                << static_cast<double>(limit) * sizeof(Key) / elapsed / 1048576 << " MB/sec.)"
                << std::endl
