    {
        Stopwatch watch;

        using Map = HashMapWithSavedHash<SmallStringView, Value>;

        Map map;
        Map::LookupResult it = {};
        bool inserted = {};

        for (size_t i = 0; i < n; ++i)
        {
            map.emplace(SmallStringView(data[i].data(), data[i].size()), it, inserted);
            if (inserted)
                it->getMapped() = 0;
            ++it->getMapped();
        }

